{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C25"],
      "claim": "Melperone, the closest analogue sharing the 4-fluorophenylbutanone piperidine scaffold, has an absolute oral bioavailability of 67 ± 28% in healthy volunteers, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C50"],
      "claim": "Haloperidol, a closely related butyrophenone antipsychotic, has an absolute oral bioavailability of 0.70 ± 0.18 in humans, supporting high bioavailability for this structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Bromperidol, another direct butyrophenone analogue, has an oral bioavailability of 30% in humans, still above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Ketanserin, which combines a 4-fluorobenzoyl piperidine with a fused heterocycle, has an absolute bioavailability of 45 ± 7%, supporting high F for the query's hybrid scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Lumateperone, a more complex butyrophenone-derived antipsychotic, has an absolute bioavailability of ≈4.4%, providing a low-F outlier, but its fused tetracyclic structure and unique first-pass metabolism limit transferability to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C31"],
      "claim": "A benzimidazole-piperidine antihistamine-like analogue has an absolute oral bioavailability of 3% in humans, another low-F outlier with limited structural transfer to the butyrophenone query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is benperidol, a butyrophenone antipsychotic. The closest analogues sharing the 4-fluorophenylbutanone/piperidine scaffold (melperone, haloperidol, bromperidol) and the 4-fluorobenzoyl-piperidine-fused-heterocycle analogue ketanserin all show absolute oral bioavailability of 30–70%, well above the 20% threshold. The low-F outliers are structurally more remote and their poor bioavailability reflects unique fused-ring/first-pass liabilities, so high bioavailability is predicted.",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement for benperidol itself is present in the provided evidence set.",
    "Lumateperone demonstrates that a butyrophenone-derived antipsychotic can have very low F, so first-pass metabolism differences remain a source of uncertainty.",
    "No query-specific formulation, dose, or food-effect data are available."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

